#!/usr/bin/env ruby
# frozen_string_literal: true

# Makes the `App` target the native SwiftUI phone app and adds its smoke tests.
#
# The target was generated by `npx cap add ios` as a webview shell; this strips what Capacitor put
# there (its SPM package, the web bundle folder, its config files, the storyboard it booted from),
# adds every Swift file under `App/App/Sources` in groups mirroring the folders, links the
# packages the app is built on, and adds the `AppUITests` UI-test target to the `App` scheme.
#
# Idempotent: re-run it after adding or moving a Swift file, and commit the resulting project.
#
#   cd apps/frontend/ios && ruby wire_native_app.rb
require "xcodeproj"

PROJ = File.expand_path("App/App.xcodeproj", __dir__)
TEAM = "464K6UHCU4"
APP_TARGET = "App"
TEST_TARGET = "AppUITests"
DEPLOYMENT_TARGET = "18.0"
SOURCES = File.expand_path("App/App/Sources", __dir__)
TEST_SOURCES = File.expand_path("App/AppUITests", __dir__)

project = Xcodeproj::Project.open(PROJ)
app = project.targets.find { |t| t.name == APP_TARGET } or raise "App target not found"
app_group = project.main_group.children.find { |c| c.display_name == APP_TARGET } or raise "App group not found"

# --- what Capacitor left ---------------------------------------------------
CAPACITOR_FILES = %w[public capacitor.config.json config.xml Main.storyboard AppDelegate.swift SceneDelegate.swift
                     WatchHandoffPlugin.swift IcsImportPlugin.swift HealthKitPlugin.swift DailyIconManager.swift].freeze
app.build_phases.each do |phase|
  phase.files.dup.each do |bf|
    bf.remove_from_project if bf.file_ref && CAPACITOR_FILES.include?(bf.file_ref.display_name)
  end
end
app_group.children.dup.each { |c| c.remove_from_project if CAPACITOR_FILES.include?(c.display_name) }

app.package_product_dependencies.dup.each do |dep|
  next unless dep.product_name == "CapApp-SPM"

  app.frameworks_build_phase.files.dup.each { |bf| bf.remove_from_project if bf.product_ref == dep }
  dep.remove_from_project
end
project.root_object.package_references.dup.each do |ref|
  next unless ref.respond_to?(:relative_path) && ref.relative_path == "CapApp-SPM"

  project.root_object.package_references.delete(ref)
  ref.remove_from_project
end

# `debug.xcconfig` only ever set CAPACITOR_DEBUG.
app.build_configurations.each { |c| c.base_configuration_reference = nil }
project.main_group.children.dup.each { |c| c.remove_from_project if c.display_name == "debug.xcconfig" }

# Every run of an older wiring script added one more empty "Embed Watch Content" phase.
embeds = app.build_phases.grep(Xcodeproj::Project::Object::PBXCopyFilesBuildPhase).select { |p| p.name == "Embed Watch Content" }
keep = embeds.find { |p| !p.files.empty? }
(embeds - [keep]).each { |p| app.build_phases.delete(p); p.remove_from_project }

# --- settings ---------------------------------------------------------------
app.build_configurations.each do |config|
  s = config.build_settings
  s["IPHONEOS_DEPLOYMENT_TARGET"] = DEPLOYMENT_TARGET
  s["DEVELOPMENT_TEAM"] = TEAM
  s["SWIFT_VERSION"] = "5.0"
  s["ENABLE_PREVIEWS"] = "YES"
  s["CODE_SIGN_ENTITLEMENTS"] = "App/App.entitlements"
  s.delete("OTHER_SWIFT_FLAGS")
  s["SWIFT_ACTIVE_COMPILATION_CONDITIONS"] = config.name == "Debug" ? "DEBUG" : ""
end
project.build_configurations.each { |c| c.build_settings["IPHONEOS_DEPLOYMENT_TARGET"] = DEPLOYMENT_TARGET }

# --- sources ----------------------------------------------------------------
app_group.children.dup.each { |c| c.remove_from_project if c.display_name == "Sources" }
app.source_build_phase.files.dup.each { |bf| bf.remove_from_project if bf.file_ref.nil? }

def mirror(group, dir, target)
  Dir.children(dir).sort.each do |name|
    path = File.join(dir, name)
    if File.directory?(path)
      mirror(group.new_group(name, name), path, target)
    elsif name.end_with?(".swift")
      target.add_file_references([group.new_reference(name)])
    end
  end
end
mirror(app_group.new_group("Sources", "Sources"), SOURCES, app)

# --- packages ---------------------------------------------------------------
kit = project.root_object.package_references.find { |r| r.respond_to?(:relative_path) && r.relative_path == "../BalanceKit" }
raise "BalanceKit package reference missing — run wire_watch_targets.rb first" unless kit

google = project.root_object.package_references.find { |r| r.respond_to?(:repositoryURL) && r.repositoryURL.to_s.include?("GoogleSignIn-iOS") }
unless google
  google = project.new(Xcodeproj::Project::Object::XCRemoteSwiftPackageReference)
  google.repositoryURL = "https://github.com/google/GoogleSignIn-iOS"
  google.requirement = { "kind" => "upToNextMajorVersion", "minimumVersion" => "9.0.0" }
  project.root_object.package_references << google
end

def link(project, target, package, product)
  return if target.package_product_dependencies.any? { |d| d.product_name == product }

  dependency = project.new(Xcodeproj::Project::Object::XCSwiftPackageProductDependency)
  dependency.package = package
  dependency.product_name = product
  target.package_product_dependencies << dependency
  build_file = project.new(Xcodeproj::Project::Object::PBXBuildFile)
  build_file.product_ref = dependency
  target.frameworks_build_phase.files << build_file
end

%w[BalanceKit BalanceCore BalanceTelemetry ClerkKit].each { |p| link(project, app, kit, p) }
link(project, app, google, "GoogleSignIn")

# --- UI tests ---------------------------------------------------------------
if (old = project.targets.find { |t| t.name == TEST_TARGET })
  project.targets.each { |t| t.dependencies.dup.each { |d| d.remove_from_project if d.target == old } }
  old.product_reference&.remove_from_project
  old.remove_from_project
end
project.main_group.children.dup.each { |c| c.remove_from_project if c.display_name == TEST_TARGET }

tests = project.new_target(:ui_test_bundle, TEST_TARGET, :ios, DEPLOYMENT_TARGET, nil, :swift)
test_group = project.main_group.new_group(TEST_TARGET, "App/AppUITests")
tests.add_file_references(Dir[File.join(TEST_SOURCES, "*.swift")].sort.map { |f| test_group.new_reference(File.basename(f)) })
tests.add_dependency(app)
tests.build_configurations.each do |config|
  s = config.build_settings
  s["TEST_TARGET_NAME"] = APP_TARGET
  s["PRODUCT_BUNDLE_IDENTIFIER"] = "com.elumixor.balance.uitests"
  s["DEVELOPMENT_TEAM"] = TEAM
  s["CODE_SIGN_STYLE"] = "Automatic"
  s["GENERATE_INFOPLIST_FILE"] = "YES"
  s["SWIFT_VERSION"] = "5.0"
  s["TARGETED_DEVICE_FAMILY"] = "1,2"
end

project.save

# --- scheme -----------------------------------------------------------------
# The `App` scheme runs the phone app and its smoke tests; fastlane's release lane asks for it by
# name, so it stays shared.
scheme = Xcodeproj::XCScheme.new
scheme.add_build_target(app)
scheme.set_launch_target(app)
scheme.add_test_target(tests)
scheme.save_as(PROJ, APP_TARGET, true)

puts "Wired the native #{APP_TARGET} target (#{app.source_build_phase.files.count} sources) and #{TEST_TARGET}"
